final List<FlashKart> sozelKartlar = [
  // ─── TÜRKÇE ────────────────────────────────────────────
  _k('ktr-001', 'turkce', 'Ses Bilgisi', 'Ünlü düşmesi', 'İkinci hecesinde dar ünlü (ı, i, u, ü) bulunan bazı sözcükler ünlüyle başlayan ek alınca bu ünlüyü düşürür: ağız → ağzı, burun → burnu, oğul → oğlu.\nBirleşik sözcüklerde de görülür: kayın + ana → kaynana.', 'Ağzı, burnu'),
  _k('ktr-002', 'turkce', 'Ses Bilgisi', 'Ünlü daralması', '“a, e” ile biten fiillere -yor eki gelince bu ünlüler daralır: başla-yor → başlıyor, izle-yor → izliyor.\nDemek ve yemek fiillerinde -y- ile başlayan eklerde de olur: diyecek, yiyen.', '-yor eki'),
  _k('ktr-003', 'turkce', 'Ses Bilgisi', 'Ünsüz yumuşaması', 'Sonu p, ç, t, k ile biten sözcükler ünlüyle başlayan ek alınca b, c, d, ğ/g olur: kitap → kitabı, ağaç → ağacı, renk → rengi.\nTek heceli sözcüklerin çoğunda görülmez: top-u, saç-ı.', 'P Ç T K → B C D Ğ'),
  _k('ktr-004', 'turkce', 'Ses Bilgisi', 'Ünsüz benzeşmesi (sertleşme)', 'Sert ünsüzle (f, s, t, k, ç, ş, h, p) biten sözcüğe c, d, g ile başlayan ek gelince ekin ünsüzü sertleşir: kitap-çı, sınıf-ta, süt-çü.\nSert ünsüzleri hatırlamak için: “FıSTıKÇı ŞaHaP”.', 'FıSTıKÇı ŞaHaP'),
  _k('ktr-005', 'turkce', 'Ses Bilgisi', 'Ünsüz türemesi', 'Bazı Arapça kökenli sözcüklerde ek ya da yardımcı fiil gelince ünsüz ikizleşir: his → hissetmek, af → affetmek, zan → zannetmek, hak → hakkı.', 'His → hisset'),
  _k('ktr-006', 'turkce', 'Ses Bilgisi', 'Kaynaştırma ünsüzleri', 'Ünlüyle biten sözcüğe ünlüyle başlayan ek gelince araya y, ş, s, n girer: masa-y-ı, iki-şer, oda-s-ı, kapı-n-ın.\nHatırlatma: “Yeşil Su Nehri”', 'y, ş, s, n'),
  _k('ktr-007', 'turkce', 'Sözcük Türleri', 'İsim tamlaması türleri', 'Belirtili: iki öğe de ek alır (kalemin ucu)\nBelirtisiz: yalnız tamlanan ek alır (okul bahçesi)\nZincirleme: en az üç isimden oluşur (evin bahçe kapısı)\nTakısız: iki öğe de ek almaz, benzetme bildirir (demir yumruk)', 'Tamlayan + tamlanan'),
  _k('ktr-008', 'turkce', 'Sözcük Türleri', 'Zamir (adıl) türleri', 'Kişi (ben, sen), işaret (bu, şu), belgisiz (biri, hepsi, kimse), soru (kim, ne), dönüşlülük (kendi), ilgi zamiri (-ki: benimki, seninki).\nZamir ismin yerini tutar; sıfat ise ismi niteler.', 'Yerini tutar'),
  _k('ktr-009', 'turkce', 'Sözcük Türleri', 'Zarf (belirteç) türleri', 'Durum (hızlı koştu), zaman (yarın gel), yer-yön (içeri gir), miktar (çok yorgun), soru (nasıl, ne zaman).\nZarflar fiili, sıfatı ya da başka bir zarfı niteler.', 'Fiili niteler'),
  _k('ktr-010', 'turkce', 'Sözcük Türleri', 'Edat (ilgeç)', 'Tek başına anlamı olmayan, cümleye anlam ilişkisi katan sözcükler: gibi, için, kadar, göre, ile, ancak, yalnız, sadece, dolayı, rağmen.', 'Gibi, için, kadar'),
  _k('ktr-011', 'turkce', 'Sözcük Türleri', 'Bağlaçlar', 'Sözcükleri veya cümleleri bağlar: ve, veya, ama, fakat, ancak, çünkü, hem… hem, ne… ne, ya… ya, de/da, ki.\nBağlaç olan “de/da” ve “ki” ayrı yazılır.', 'Cümleden çıkarınca anlam daralır'),
  _k('ktr-012', 'turkce', 'Fiilimsiler', 'Fiilimsi (eylemsi) türleri', 'İsim-fiil: -ma, -ış, -mak (okumak güzeldir)\nSıfat-fiil: -an, -ası, -maz, -ar, -dık, -acak, -mış (gelen misafir)\nZarf-fiil: -ıp, -ınca, -arak, -madan, -dıkça, -alı, -ken (gülerek geldi)', 'Mak-Ma-Iş / An-Ası-Mez / Ip-Ince-Arak'),
  _k('ktr-013', 'turkce', 'Fiiller', 'Fiilde çatı', 'Nesnesine göre: geçişli (nesne alır), geçişsiz (nesne almaz)\nÖznesine göre: etken (özne belli), edilgen (-l, -n; sözde özne), dönüşlü (-n, -ş; kendine yapar), işteş (-ş; birlikte yapar)', 'Nesne / özne'),
  _k('ktr-014', 'turkce', 'Cümle Bilgisi', 'Cümlenin ögeleri', 'Yüklem: iş ya da oluş bildirir\nÖzne: işi yapan (kim? ne?)\nNesne: işten etkilenen (neyi? kimi? ne?)\nDolaylı tümleç: -e, -de, -den (nereye? nerede? nereden?)\nZarf tümleci: nasıl? ne zaman? niçin?\nEdat tümleci: ile, için, gibi', 'Önce yüklemi bul'),
  _k('ktr-015', 'turkce', 'Cümle Bilgisi', 'Yapılarına göre cümleler', 'Basit: tek yargı\nBirleşik: girişik (fiilimsili), şartlı (-sa), ki\'li, iç içe (alıntı)\nSıralı: virgül/noktalı virgülle bağlı yargılar\nBağlı: bağlaçla bağlanan yargılar', 'Fiilimsi = girişik'),
  _k('ktr-016', 'turkce', 'Anlatım Bozuklukları', 'Anlama dayalı bozukluklar', 'Gereksiz sözcük (yaklaşık 20 kadar), yanlış anlamda sözcük, çelişen anlatım (kesinlikle belki), mantık hatası, deyim yanlışı, ekle ilgili anlam kayması, sıralama yanlışı.', 'Yaklaşık … kadar'),
  _k('ktr-017', 'turkce', 'Anlatım Bozuklukları', 'Yapıya dayalı bozukluklar', 'Özne-yüklem uyumsuzluğu, eksik öge (özne/nesne/tümleç), tamlama yanlışı, çatı uyuşmazlığı (etken-edilgen ortak kullanım), ek eksikliği ya da fazlalığı, yanlış bağlaç kullanımı.', 'Ortak öge kontrolü'),
  _k('ktr-018', 'turkce', 'Paragraf', 'Anlatım biçimleri', 'Açıklayıcı: bilgi verir\nTartışmacı: bir görüşü savunur, karşı görüşü çürütür\nÖyküleyici: olay, zaman, kişi vardır\nBetimleyici: sözcüklerle resim çizer, duyulara hitap eder', 'Betimleme = resim'),
  _k('ktr-019', 'turkce', 'Paragraf', 'Düşünceyi geliştirme yolları', 'Tanımlama (… demektir), örneklendirme (örneğin), karşılaştırma (-den daha), tanık gösterme (ünlü birinin sözü), sayısal verilerden yararlanma (%, rakamlar), benzetme (gibi).', 'Tanık = alıntı'),
  _k('ktr-020', 'turkce', 'Yazım Kuralları', '“de/da” bağlacı ile hâl eki', 'Bağlaç “de/da” ayrı yazılır, cümleden çıkarılınca anlam daralır ama bozulmaz: Ben de geldim.\nHâl eki “-de/-da, -te/-ta” bitişik yazılır: Evde, sınıfta.', 'Çıkar, cümle bozuluyor mu?'),
  _k('ktr-021', 'turkce', 'Yazım Kuralları', '“ki”nin yazımı', 'Bağlaç “ki” ayrı yazılır: Duydum ki gelmişsin.\nSıfat yapan -ki (yarınki, evdeki) ve ilgi zamiri -ki (benimki) bitişiktir.\nKalıplaşmışlar bitişik: belki, çünkü, sanki, oysaki, mademki, hâlbuki, meğerki.', 'Belki, çünkü bitişik'),
  _k('ktr-022', 'turkce', 'Yazım Kuralları', 'Soru eki “mı/mi”', 'Soru eki ayrı yazılır, önündeki sözcüğün ünlüsüne uyar ve kendisinden sonraki ekler ona bitişir: Geldin mi? Yorgun musun? Okula mı gidiyorsun?', 'Ayrı ama uyumlu'),
  _k('ktr-023', 'turkce', 'Yazım Kuralları', 'Büyük harflerin kullanımı', 'Cümle başı, özel adlar, unvanlar özel adla birlikte (Ali Bey, Doktor Ayşe), belirli bir tarih bildiren ay ve gün adları (29 Ekim 1923 Pazartesi), kurum adları (Türk Dil Kurumu).\nTarih bildirmeyen ay adları küçük yazılır: Her yıl ekimde…', 'Belirli tarih büyük'),
  _k('ktr-024', 'turkce', 'Noktalama İşaretleri', 'Kesme işareti', 'Özel adlara gelen ekleri ayırır: Ankara\'ya, Atatürk\'ün.\nKısaltmalara ve sayılara gelen ekler: TDK\'nin, 1923\'te.\nKurum, kuruluş, kitap adlarına gelen ekler ayrılmaz: Türk Dil Kurumunun.', 'Kurum adında kesme yok'),
  _k('ktr-025', 'turkce', 'Noktalama İşaretleri', 'Noktalı virgül ve iki nokta', 'Noktalı virgül: ögeleri virgülle ayrılmış tür veya takımları ayırır; bağlaçtan önce ögeler arasında kullanılabilir.\nİki nokta: kendisinden sonra örnek veya açıklama verilecek cümlelerin sonuna konur.', 'İki nokta = açıklama gelecek'),
  _k('ktr-026', 'turkce', 'Sözcükte Anlam', 'Gerçek, yan, mecaz ve terim anlam', 'Gerçek: ilk akla gelen (ağır bavul)\nYan: gerçek anlamla ilgili yeni anlam (masanın ayağı)\nMecaz: gerçek anlamdan tamamen uzak (ağır söz)\nTerim: bir bilim/sanat dalına özgü (açı, üçgen)', 'Ağır bavul / ağır söz'),
  _k('ktr-027', 'turkce', 'Söz Öbekleri', 'Deyim ile atasözü farkı', 'Deyim: çoğunlukla mecaz anlamlı kalıplaşmış söz öbeğidir, yargı bildirmeyebilir (göz atmak).\nAtasözü: toplumun ortak deneyimini yansıtan, öğüt veren, kalıplaşmış yargı cümlesidir (Damlaya damlaya göl olur).', 'Atasözü öğüt verir'),
  _k('ktr-028', 'turkce', 'Cümlede Anlam', 'Öznel ve nesnel yargı', 'Öznel: kişisel görüş, beğeni; kanıtlanamaz (Bu roman çok sürükleyici.)\nNesnel: kanıtlanabilir, herkes için aynı (Roman 1922\'de yayımlandı.)', 'Kanıtlanabilir mi?'),
  _k('ktr-029', 'turkce', 'Cümlede Anlam', 'Cümle anlam ilişkileri', 'Neden-sonuç: -dığı için, -den dolayı\nAmaç-sonuç: -mek için, amacıyla\nKoşul-sonuç: -se, -dıkça\nKarşılaştırma: -den daha\nÖnerme: -meli, -se iyi olur', 'Amaç ile neden farkı'),
  _k('ktr-030', 'turkce', 'Yapı Bilgisi', 'Yapım ve çekim ekleri', 'Yapım eki yeni sözcük türetir: göz-lük, yaz-ar, sev-gi.\nÇekim eki sözcüğün anlamını değiştirmez, cümledeki görevini belirler: ev-ler, ev-e, gel-di.\nYapım ekleri çekim eklerinden önce gelir.', 'Göz-lük-ler'),

  // ─── EDEBİYAT (ek) ─────────────────────────────────────
  _k('kedb-001', 'edebiyat', 'İslamiyet Öncesi', 'Sözlü edebiyat türleri', 'Koşuk (şölen ve doğa, yiğitlik), sagu (ölüm, yas), sav (atasözü), destan.\nNazım birimi dörtlük, ölçü hece, kafiye yarım ve genellikle sonda.', 'Sagu = ağıt'),
  _k('kedb-002', 'edebiyat', 'Geçiş Dönemi', 'Divanü Lügati\'t-Türk', 'Kaşgarlı Mahmut (1072-1074). Araplara Türkçe öğretmek amacıyla yazılmış ilk Türkçe sözlük; sav, sagu ve koşuk örneklerini içerir.', 'İlk Türkçe sözlük'),
  _k('kedb-003', 'edebiyat', 'Geçiş Dönemi', 'Atabetü\'l-Hakayık ve Divan-ı Hikmet', 'Atabetü\'l-Hakayık: Edip Ahmet Yükneki, didaktik (öğretici) ahlak kitabı.\nDivan-ı Hikmet: Hoca Ahmet Yesevi\'nin tasavvufi şiirleri (hikmet).', 'Yükneki / Yesevi'),
  _k('kedb-004', 'edebiyat', 'Divan Edebiyatı', 'Fuzuli', '16. yüzyıl. Aşk ve ıstırap şairi. “Leyla vü Mecnun” mesnevisi, “Su Kasidesi”, “Şikâyetname” (mektup). Türkçe, Arapça ve Farsça divanları vardır.', 'Leyla vü Mecnun'),
  _k('kedb-005', 'edebiyat', 'Divan Edebiyatı', 'Baki', '16. yüzyıl, “Sultanü\'ş-şuara” (şairler sultanı). Kanuni için yazdığı mersiye ünlüdür. Dünya hayatını, sevinci ve söz ustalığını işler.', 'Kanuni Mersiyesi'),
  _k('kedb-006', 'edebiyat', 'Divan Edebiyatı', 'Nedim ve Şeyh Galip', 'Nedim: Lale Devri şairi, İstanbul\'u ve eğlence hayatını anlattı; şarkı türünün ustası, mahallileşme akımının temsilcisi.\nŞeyh Galip: “Hüsn ü Aşk” mesnevisi, Sebk-i Hindî akımının son büyük temsilcisi.', 'Nedim = Lale Devri'),
  _k('kedb-007', 'edebiyat', 'Divan Edebiyatı', 'Nef\'i', '17. yüzyıl. Kaside türünün en büyük ustası; hiciv (yergi) şiirleri “Siham-ı Kaza” adlı eserindedir.', 'Kaside ve hiciv'),
  _k('kedb-008', 'edebiyat', 'Halk Edebiyatı', 'Âşık tarzı şairler', 'Karacaoğlan: aşk ve doğa (güzellemeler)\nKöroğlu: koçaklama\nDadaloğlu: yiğitlik, “Ferman padişahınsa dağlar bizimdir.”\nPir Sultan Abdal: tekke, isyan\nÂşık Veysel: 20. yüzyıl, “Uzun ince bir yoldayım.”', 'Dadaloğlu = ferman'),
  _k('kedb-009', 'edebiyat', 'Tekke Edebiyatı', 'Yunus Emre', '13-14. yüzyıl. Tasavvufi halk şiirinin kurucusu. Sade Türkçe, hece ölçüsü, ilahi türü. “Risaletü\'n-Nushiyye” (mesnevi) ve Divan\'ı vardır.', 'İlahi'),
  _k('kedb-010', 'edebiyat', 'Nazım Biçimleri', 'Gazel ve kaside', 'Gazel: aşk ve şarap konulu, 5-15 beyit, aa ba ca… kafiyeli. Şairin adının geçtiği beyit “makta”.\nKaside: din büyüklerini, devlet adamlarını övme; 33-99 beyit; bölümleri nesib, girizgâh, methiye, fahriye, dua.', 'Gazel aşk, kaside övgü'),
  _k('kedb-011', 'edebiyat', 'Nazım Biçimleri', 'Koşma, semai, varsağı, mani', 'Koşma: 11\'li hece, 3-5 dörtlük, âşık tarzının en yaygın biçimi\nSemai: 8\'li hece, özel bir ezgiyle\nVarsağı: 8\'li hece, “bre, hey” gibi söyleyişler\nMani: 7\'li hece, tek dörtlük, aaxa kafiye', 'Koşma 11, semai 8, mani 7'),
  _k('kedb-012', 'edebiyat', 'Nazım Biçimleri', 'Rubai ve tuyuğ', 'Rubai: aruzla, 4 dizeli, felsefi-tasavvufi; aaxa kafiyeli. İran kökenli.\nTuyuğ: aruzun tek kalıbıyla (fâilâtün fâilâtün fâilün), 4 dizeli; Türklerin divan şiirine kattığı biçim.', 'Tuyuğ Türk icadı'),
  _k('kedb-013', 'edebiyat', 'Tanzimat', 'Tanzimat II. dönem', '“Sanat sanat içindir” anlayışı. Recaizade Mahmut Ekrem (Araba Sevdası), Abdülhak Hâmit Tarhan (Makber, Tarhan), Samipaşazade Sezai (Sergüzeşt; esaret konusu), Nabizade Nazım (Karabibik; ilk köy romanı).', 'Sergüzeşt = esaret'),
  _k('kedb-014', 'edebiyat', 'Fecr-i Ati', 'Ahmet Haşim ve Fecr-i Ati', '1909\'da kuruldu, “Sanat şahsi ve muhteremdir.” Sembolizmi benimsedi.\nAhmet Haşim: “Göl Saatleri”, “Piyale”; şiirde anlam kapalılığı, musiki, “Merdiven” şiiri.', 'Sanat şahsi ve muhteremdir'),
  _k('kedb-015', 'edebiyat', 'Millî Edebiyat', 'Yeni Lisan hareketi', '1911\'de Genç Kalemler dergisinde yayımlanan “Yeni Lisan” makalesiyle başladı (Ömer Seyfettin, Ali Canip, Ziya Gökalp). Sade Türkçe, İstanbul Türkçesi, hece ölçüsü, yabancı dil kurallarının atılması.', 'Genç Kalemler 1911'),
  _k('kedb-016', 'edebiyat', 'Cumhuriyet Dönemi', 'Yedi Meşaleciler', '1928\'de “Yedi Meşale” adlı kitapla ortaya çıktılar. Hece ölçüsüyle yazdılar ancak Beş Hececilerin sınırlı konularını aşmak istediler. Sabri Esat Siyavuşgil, Ziya Osman Saba, Cevdet Kudret…', 'Yedi Meşale 1928'),
  _k('kedb-017', 'edebiyat', 'Cumhuriyet Dönemi', 'Garip akımı', '1941\'de “Garip” kitabıyla: Orhan Veli Kanık, Melih Cevdet Anday, Oktay Rifat. Ölçü, uyak ve söz sanatlarını reddettiler; sıradan insanı ve günlük dili şiire taşıdılar.', 'Sıradan insan'),
  _k('kedb-018', 'edebiyat', 'Cumhuriyet Dönemi', 'İkinci Yeni', '1950\'lerde Garip\'e tepki olarak doğdu. Anlamı kapalı, imge yoğun, soyut şiir. Cemal Süreya, Edip Cansever, Turgut Uyar, İlhan Berk, Ece Ayhan, Sezai Karakoç.', 'İmge ve kapalılık'),
  _k('kedb-019', 'edebiyat', 'Cumhuriyet Dönemi', 'Toplumcu gerçekçiler', 'Toplumsal sorunları, emekçi insanı gerçekçi bir dille işlerler. Sabahattin Ali (Kuyucaklı Yusuf, İçimizdeki Şeytan), Orhan Kemal (Bereketli Topraklar Üzerinde), Kemal Tahir, Yaşar Kemal.', 'Kuyucaklı Yusuf'),
  _k('kedb-020', 'edebiyat', 'Cumhuriyet Dönemi', 'Köy edebiyatı', '1950\'lerden sonra köy enstitüsü kökenli yazarlar köyü içeriden anlattı: Fakir Baykurt (Yılanların Öcü), Mahmut Makal (Bizim Köy), Talip Apaydın.', 'Köy enstitüleri'),
  _k('kedb-021', 'edebiyat', 'Cumhuriyet Dönemi', 'Ahmet Hamdi Tanpınar', 'Bergson\'un zaman ve bilinç anlayışından etkilendi. Romanları: Huzur, Saatleri Ayarlama Enstitüsü; denemesi: Beş Şehir. Şiirleri “Bütün Şiirleri”nde.', 'Beş Şehir'),
  _k('kedb-022', 'edebiyat', 'Cumhuriyet Dönemi', 'Reşat Nuri Güntekin ve Peyami Safa', 'Reşat Nuri: Çalıkuşu, Yaprak Dökümü; Anadolu\'yu ve toplumsal değişimi anlattı.\nPeyami Safa: Dokuzuncu Hariciye Koğuşu, Fatih-Harbiye; psikolojik roman, Doğu-Batı çatışması.', 'Çalıkuşu / Fatih-Harbiye'),
  _k('kedb-023', 'edebiyat', 'Cumhuriyet Dönemi', 'Sait Faik Abasıyanık', 'Durum (kesit, Çehov tarzı) hikâyesinin Türk edebiyatındaki en önemli temsilcisi. Semaver, Sarnıç, Alemdağ\'da Var Bir Yılan. Deniz ve kıyı insanlarını anlattı.', 'Durum hikâyesi'),
  _k('kedb-024', 'edebiyat', 'Türler', 'Olay ve durum hikâyesi', 'Olay (Maupassant) tarzı: serim-düğüm-çözüm planı, merak unsuru; Türk edebiyatında Ömer Seyfettin.\nDurum (Çehov) tarzı: belirgin bir olay örgüsü yok, hayattan bir kesit; Sait Faik, Memduh Şevket Esendal.', 'Maupassant / Çehov'),
  _k('kedb-025', 'edebiyat', 'Türler', 'Öğretici metin türleri', 'Makale: bilgi verir, kanıtlar, resmî dil\nDeneme: kişisel görüş, samimi, kesin yargı yok (Montaigne)\nFıkra: güncel olayı kısa yorumlar (köşe yazısı)\nSohbet (söyleşi): okuyucuyla konuşur gibi\nEleştiri: eseri değerlendirir', 'Deneme = Montaigne'),
  _k('kedb-026', 'edebiyat', 'Türler', 'Anı, günlük, biyografi', 'Anı (hatıra): yaşanmış olayların sonradan yazılması\nGünlük: günü gününe, tarih atılarak yazılır\nBiyografi: başkasının hayatı\nOtobiyografi: kişinin kendi hayatı', 'Günlük = tarihli'),
  _k('kedb-027', 'edebiyat', 'Dede Korkut', 'Dede Korkut Hikâyeleri', 'Oğuz Türklerinin destan döneminden yerleşik hayata geçişini anlatan 12 hikâye (Dresden ve Vatikan nüshaları). Nazım-nesir karışık; halk hikâyesine geçiş örneğidir.', '12 hikâye'),
  _k('kedb-028', 'edebiyat', 'Söz Sanatları', 'İstiare, kinaye, teşhis', 'İstiare: benzetmenin temel öğelerinden yalnız biriyle yapılan benzetme (açık/kapalı istiare)\nKinaye: sözün hem gerçek hem mecaz anlamının düşünülmesi, mecazın kastedilmesi\nTeşhis: insan dışı varlıklara insan özelliği vermek', 'Tek öğeli benzetme'),
  _k('kedb-029', 'edebiyat', 'Söz Sanatları', 'Tecahül-i arif ve hüsn-i talil', 'Tecahül-i arif: bilip de bilmezlikten gelme\nHüsn-i talil: bir olayı gerçek nedeninin dışında güzel bir nedene bağlama\nMübalağa: abartma\nTelmih: bilinen bir olaya gönderme', 'Güzel neden bulma'),
  _k('kedb-030', 'edebiyat', 'Cumhuriyet Dönemi', 'Necip Fazıl ve Cahit Sıtkı', 'Necip Fazıl Kısakürek: “Çile”, “Kaldırımlar”; mistik ve metafizik şiir, tiyatro (Bir Adam Yaratmak).\nCahit Sıtkı Tarancı: “Otuz Beş Yaş”; ölüm ve yaşama sevinci temaları.', 'Kaldırımlar / Otuz Beş Yaş'),

  // ─── TARİH (ek) ────────────────────────────────────────
  _k('ktar-001', 'tarih', 'İlk Türk Devletleri', 'Asya Hun Devleti ve Mete Han', 'Bilinen ilk Türk devleti. Mete Han, orduyu onlu sisteme göre düzenledi (günümüz Türk Kara Kuvvetlerinin kuruluş tarihi M.Ö. 209 kabul edilir). Çin\'le mücadele Çin Seddi\'nin yapılmasına yol açtı.', 'Onlu sistem'),
  _k('ktar-002', 'tarih', 'İlk Türk Devletleri', 'Kavimler Göçü (375)', 'Hunların batıya ilerlemesiyle Avrupa\'da kavimlerin yer değiştirmesi. Sonuçları: Roma\'nın ikiye ayrılması (395), feodalitenin doğması, bugünkü Avrupa milletlerinin temellerinin atılması.', 'Roma ikiye ayrıldı'),
  _k('ktar-003', 'tarih', 'İlk Türk Devletleri', 'Orhun Abideleri', 'II. Göktürk Devleti döneminde Bilge Kağan, Kül Tigin ve Vezir Tonyukuk adına dikildi (8. yüzyıl). Türk adının geçtiği, Türklere ait ilk yazılı belgelerdendir.', 'Bilge Kağan'),
  _k('ktar-004', 'tarih', 'Türk-İslam Devletleri', 'Karahanlılar ve Gazneliler', 'Karahanlılar: İslamiyet\'i resmî din olarak kabul eden ilk Türk devletlerinden (Satuk Buğra Han); Türkçeyi resmî dil olarak kullandılar.\nGazneliler: Sultan Mahmut\'un Hindistan seferleri; İslamiyet\'in Hindistan\'da yayılması.', 'Satuk Buğra Han'),
  _k('ktar-005', 'tarih', 'Türk-İslam Devletleri', 'Büyük Selçuklu Devleti', 'Dandanakan Savaşı (1040) ile kuruldu. Tuğrul Bey 1055\'te Bağdat\'a girip halifeyi Büveyhoğulları baskısından kurtardı. Vezir Nizamülmülk: Nizamiye medreseleri ve Siyasetname.', 'Dandanakan 1040'),
  _k('ktar-006', 'tarih', 'Türkiye Tarihi', 'Kösedağ Savaşı (1243)', 'Anadolu Selçukluları ile İlhanlılar (Moğollar) arasında yapıldı. Selçuklular yenilip Moğol egemenliğine girdi; Anadolu\'da siyasi birlik bozuldu, beylikler dönemi başladı.', 'Moğol egemenliği'),
  _k('ktar-007', 'tarih', 'Osmanlı Kuruluş', 'Kuruluş dönemi savaşları', 'Koyunhisar/Bafeus (1302): Bizans\'la ilk savaş\nSırpsındığı (1364): Haçlılara karşı ilk zafer\nI. Kosova (1389), Niğbolu (1396)\nAnkara Savaşı (1402): Timur\'a yenilgi, Fetret Devri', 'Bafeus ilk savaş'),
  _k('ktar-008', 'tarih', 'Osmanlı Yükselme', 'Yavuz Sultan Selim dönemi', 'Çaldıran (1514): Safevilere karşı\nMercidabık (1516) ve Ridaniye (1517): Memlüklere karşı; halifelik Osmanlı\'ya geçti, kutsal emanetler İstanbul\'a getirildi.', 'Halifelik 1517'),
  _k('ktar-009', 'tarih', 'Osmanlı Yükselme', 'Kanuni dönemi', 'Mohaç (1526): Macaristan\'ın büyük kısmı alındı; tarihin en kısa meydan savaşlarından.\nI. Viyana Kuşatması (1529)\nPreveze (1538): Akdeniz hâkimiyeti\nFransa\'ya kapitülasyon verilmesi bu döneme dayanır (1535; resmî olarak II. Selim döneminde, 1569).', 'Mohaç 1526'),
  _k('ktar-010', 'tarih', 'Osmanlı 17. Yüzyıl', '17. yüzyıl antlaşmaları', 'Zitvatorok (1606): Avusturya imparatoru Osmanlı padişahına eşit sayıldı.\nKasr-ı Şirin (1639): İran ile bugünkü sınıra yakın sınır çizildi.\nKarlofça (1699): Osmanlı\'nın ilk büyük toprak kaybı.', 'Karlofça ilk büyük kayıp'),
  _k('ktar-011', 'tarih', 'Osmanlı 18. Yüzyıl', '18. yüzyıl antlaşmaları', 'Pasarofça (1718): Lale Devri başladı.\nKüçük Kaynarca (1774): Kırım bağımsız oldu; Rusya Ortodokslar üzerinde hak iddia etmeye başladı; ilk kez savaş tazminatı ödendi.\nYaş (1792): Kırım\'ın Rusya\'ya ait olduğu kabul edildi.', 'Küçük Kaynarca 1774'),
  _k('ktar-012', 'tarih', 'Osmanlı 19. Yüzyıl', 'II. Mahmut dönemi', 'Sened-i İttifak (1808): padişah yetkileri ilk kez sınırlandı (ayanlarla).\nVaka-i Hayriye (1826): Yeniçeri Ocağı kaldırıldı, Asakir-i Mansure-i Muhammediye kuruldu.\nİlk resmî gazete Takvim-i Vekayi (1831), ilk nüfus sayımı (1831).', 'Yeniçeri kaldırıldı 1826'),
  _k('ktar-013', 'tarih', 'Osmanlı 19. Yüzyıl', 'Kırım Savaşı ve Paris Antlaşması', 'Kırım Savaşı (1853-1856): Osmanlı, İngiltere ve Fransa ile birlikte Rusya\'ya karşı savaştı.\nParis Antlaşması (1856): Osmanlı Avrupa devleti sayıldı; Karadeniz tarafsız hâle getirildi. Osmanlı ilk dış borcunu 1854\'te aldı.', 'İlk dış borç 1854'),
  _k('ktar-014', 'tarih', 'Osmanlı 20. Yüzyıl', 'Trablusgarp ve Balkan Savaşları', 'Trablusgarp Savaşı (1911-1912): İtalya\'ya karşı; Uşi Antlaşması ile Trablusgarp ve On İki Ada (geçici) İtalya\'ya bırakıldı. Mustafa Kemal Derne ve Tobruk\'ta görev aldı.\nBalkan Savaşları (1912-1913): Rumeli\'nin büyük kısmı kaybedildi.', 'Uşi 1912'),
  _k('ktar-015', 'tarih', 'I. Dünya Savaşı', 'Çanakkale Cephesi (1915)', 'İtilaf Devletleri Boğazları geçip İstanbul\'u almak ve Rusya\'ya yardım ulaştırmak istedi. 18 Mart 1915 deniz zaferi ve kara savaşlarıyla geçilemedi. Mustafa Kemal Anafartalar\'da ün kazandı. Savaş I. Dünya Savaşı\'nı uzattı.', '18 Mart 1915'),
  _k('ktar-016', 'tarih', 'Kurtuluş Savaşı', 'Misak-ı Millî (28 Ocak 1920)', 'Son Osmanlı Mebusan Meclisi\'nde kabul edilen millî ant. Mondros imzalandığında Türk askerinin elinde bulunan yerlerin bölünmez bir bütün olduğu; Batı Trakya, Kars-Ardahan-Batum ve Arap toprakları için halk oylaması yapılacağı belirtildi.', 'Son Osmanlı Meclisi'),
  _k('ktar-017', 'tarih', 'Kurtuluş Savaşı', 'Sevr Antlaşması (10 Ağustos 1920)', 'Osmanlı Devleti ile İtilaf Devletleri arasında imzalandı ancak Osmanlı Meclis-i Mebusanı kapalı olduğu için onaylanmadı; hukuken geçersiz kaldı. TBMM, Sevr\'i imzalayanları vatan haini ilan etti.', 'Hiç yürürlüğe girmedi'),
  _k('ktar-018', 'tarih', 'Kurtuluş Savaşı', 'Mudanya Ateşkes Antlaşması (11 Ekim 1922)', 'Büyük Taarruz\'un ardından imzalandı; Doğu Trakya ve İstanbul savaş yapılmadan kurtarıldı. Osmanlı Devleti\'nin hukuken sona erdiği kabul edilir.', 'Savaşsız Doğu Trakya'),
  _k('ktar-019', 'tarih', 'Kurtuluş Savaşı', 'Saltanatın kaldırılması (1 Kasım 1922)', 'Lozan\'a hem TBMM hem İstanbul hükûmetinin çağrılması üzerine TBMM saltanatı kaldırdı. Böylece ikiliğe son verildi; son padişah Vahdettin ülkeyi terk etti.', 'Lozan daveti'),
  _k('ktar-020', 'tarih', 'Cumhuriyet', 'Ankara\'nın başkent oluşu', '13 Ekim 1923\'te kabul edildi. Kurtuluş Savaşı\'nın merkezi olması, güvenli konumu ve ulaşım ağı üzerinde bulunması etkili oldu.', '13 Ekim 1923'),
  _k('ktar-021', 'tarih', 'İnkılaplar', '3 Mart 1924 kanunları', 'Halifelik kaldırıldı.\nTevhid-i Tedrisat Kanunu ile eğitim birleştirildi.\nŞer\'iye ve Evkaf Vekâleti ile Erkân-ı Harbiye Vekâleti kaldırıldı.', 'Hilafet + eğitim birliği'),
  _k('ktar-022', 'tarih', 'İnkılaplar', 'Toplumsal inkılaplar', 'Şapka Kanunu (1925), tekke ve zaviyelerin kapatılması (1925), uluslararası saat ve takvim (1925-1926), ölçü birimleri (1931), Soyadı Kanunu (1934) ve lakap-unvanların kaldırılması.', 'Soyadı 1934'),
  _k('ktar-023', 'tarih', 'İnkılaplar', 'Hukuk alanında inkılaplar', 'Türk Medeni Kanunu (17 Şubat 1926; İsviçre\'den uyarlandı): kadın-erkek eşitliği, resmî nikâh, tek eşlilik.\nBorçlar, Ticaret ve Ceza Kanunları da çağdaş örneklerden alındı.', 'İsviçre Medeni Kanunu'),
  _k('ktar-024', 'tarih', 'Atatürk Dönemi', 'Çok partili hayat denemeleri', 'Terakkiperver Cumhuriyet Fırkası (1924): Şeyh Sait İsyanı sonrası kapatıldı (1925).\nSerbest Cumhuriyet Fırkası (1930): Menemen Olayı\'ndan önce kendini feshetti.', '1924 ve 1930'),
  _k('ktar-025', 'tarih', 'Atatürk Dönemi', 'Atatürk ilkeleri', 'Cumhuriyetçilik, Milliyetçilik, Halkçılık, Devletçilik, Laiklik, İnkılapçılık.\n1937\'de anayasaya girdi. Laiklik; din ve devlet işlerinin ayrılmasıdır.', 'Altı ok'),
  _k('ktar-026', 'tarih', 'Atatürk Dönemi Dış Politika', 'Balkan Antantı ve Sadabat Paktı', 'Balkan Antantı (1934): Türkiye, Yunanistan, Yugoslavya, Romanya; İtalya\'nın yayılmacılığına karşı.\nSadabat Paktı (1937): Türkiye, İran, Irak, Afganistan; Doğu sınırlarının güvenliği.', 'Batı ve doğu güvenliği'),
  _k('ktar-027', 'tarih', 'Atatürk Dönemi Dış Politika', 'Musul sorunu', 'Lozan\'da çözülemedi. Milletler Cemiyeti kararıyla Musul Irak\'a (İngiliz mandası) bırakıldı; 1926 Ankara Antlaşması ile Türkiye\'ye petrol gelirinin %10\'u 25 yıllığına verildi.', '1926 Ankara Antlaşması'),
  _k('ktar-028', 'tarih', 'II. Dünya Savaşı', 'Türkiye ve II. Dünya Savaşı', 'Türkiye savaşa fiilen girmedi; savaşın sonunda (Şubat 1945) Birleşmiş Milletler\'e kurucu üye olabilmek için Almanya ve Japonya\'ya sembolik olarak savaş ilan etti.', 'Sembolik savaş ilanı'),
  _k('ktar-029', 'tarih', 'Soğuk Savaş', 'Türkiye\'nin NATO\'ya girişi', 'Sovyet tehdidine karşı Batı ile yakınlaşma: Truman Doktrini (1947), Marshall Planı (1948), Kore Savaşı\'na asker gönderilmesi (1950) ve NATO üyeliği (1952).', 'NATO 1952'),
  _k('ktar-030', 'tarih', 'Dünya Tarihi', 'Coğrafi keşifler ve Rönesans', 'Coğrafi keşifler (15-16. yy): Ümit Burnu\'nun dolaşılması ve Amerika\'nın keşfi; ticaret yolları Akdeniz\'den okyanuslara kaydı.\nRönesans: İtalya\'da başlayan sanat ve bilimde yeniden doğuş.\nReform: Martin Luther ile Katolik Kilisesi\'ne tepki (1517).', 'Luther 1517'),

  // ─── COĞRAFYA (ek) ─────────────────────────────────────
  _k('kcog-001', 'cografya', 'Harita Bilgisi', 'Ölçek türleri', 'Kesir ölçek: 1/100.000\nÇizgi ölçek: cetvel şeklinde\nPaydası küçük olan ölçek büyüktür; büyük ölçekli haritada ayrıntı fazla, alan küçüktür.', 'Payda küçük = ölçek büyük'),
  _k('kcog-002', 'cografya', 'Dünya\'nın Şekli', 'Enlemin etkileri', 'Ekvator\'dan kutuplara gidildikçe: sıcaklık azalır, gece-gündüz süre farkı artar, kalıcı kar sınırı alçalır, çizgisel hız azalır, yer çekimi artar, bitki çeşitliliği azalır.', 'Kutba doğru soğur'),
  _k('kcog-003', 'cografya', 'Dünya\'nın Şekli', 'Boylam ve yerel saat', 'Dünya 360 boylamı 24 saatte döner: her boylam arası 4 dakika.\nDoğudaki yerin yerel saati ileridir.\nTürkiye 26°-45° D boylamları arasındadır; doğu ile batı arasında 76 dakika fark vardır. Ülkede UTC+3 tek saat uygulanır.', '1° = 4 dk'),
  _k('kcog-004', 'cografya', 'Türkiye\'nin Konumu', 'Türkiye\'nin matematik konumu', '36°-42° Kuzey enlemleri ile 26°-45° Doğu boylamları arasında. Kuzey Yarım Küre\'de, orta kuşakta; güneye bakan yamaçlar daha çok ısınır, dört mevsim belirgindir.', '36-42 K, 26-45 D'),
  _k('kcog-005', 'cografya', 'Yer Şekilleri', 'İç kuvvetler', 'Orojenez: dağ oluşumu (kıvrılma ve kırılma)\nEpirojenez: geniş alanların yavaş alçalıp yükselmesi\nVolkanizma: magmanın yeryüzüne çıkması\nDepremler: fay hatlarında ani kırılma', 'Orojenez = dağ'),
  _k('kcog-006', 'cografya', 'Yer Şekilleri', 'Akarsu aşındırma ve biriktirme şekilleri', 'Aşındırma: vadi (V, kanyon), dev kazanı, peribacası\nBiriktirme: delta (kıyıda, gel-git etkisi zayıfsa), birikinti yelpazesi, taşkın ovası, menderes (eğimin az olduğu yerde).\nTürkiye\'de deltalar: Çukurova, Bafra, Çarşamba, Silifke.', 'Delta = kıyı birikimi'),
  _k('kcog-007', 'cografya', 'Yer Şekilleri', 'Rüzgâr ve buzul şekilleri', 'Rüzgâr: mantar kaya, şahit tepe (aşındırma); kum tepesi, barkan, lös (biriktirme). Kurak bölgelerde etkilidir.\nBuzul: sirk, hörgüç kaya, U vadisi (aşındırma); moren (biriktirme).', 'Barkan = hilal kum tepesi'),
  _k('kcog-008', 'cografya', 'Yer Şekilleri', 'Kıyı tipleri', 'Boyuna kıyı: dağlar kıyıya paralel (Karadeniz, Akdeniz); girinti-çıkıntı az.\nEnine kıyı: dağlar kıyıya dik (Ege); girinti-çıkıntı fazla.\nRia kıyı: akarsu vadilerinin sular altında kalması (İstanbul Boğazı, Haliç).\nDalmaçya, fiyort ve limanlı kıyı diğer tiplerdir.', 'Ege = enine'),
  _k('kcog-009', 'cografya', 'Kayaçlar', 'Kayaç türleri', 'Magmatik (püskürük): granit (derinlik), bazalt (yüzey)\nTortul: kalker, kum taşı, kömür\nBaşkalaşım (metamorfik): mermer (kalkerden), gnays (granitten), kuvarsit', 'Mermer = başkalaşım'),
  _k('kcog-010', 'cografya', 'İklim', 'Basınç kuşakları ve sürekli rüzgârlar', 'Ekvator (0°): dinamik alçak basınç\n30° enlemleri: dinamik yüksek\n60° enlemleri: dinamik alçak\nKutuplar: termik yüksek\nRüzgârlar: alizeler (30°→0°), batı rüzgârları (30°→60°), kutup rüzgârları.', 'Alize → Ekvator'),
  _k('kcog-011', 'cografya', 'İklim', 'Yerel rüzgârlar', 'Meltem: kara-deniz ve dağ-vadi arasındaki günlük sıcaklık farkıyla\nFön: dağı aşıp inen sıcak ve kuru rüzgâr (karların erimesi, çığ)\nTürkiye\'de: poyraz (KD), lodos (GB), karayel (KB), keşişleme (GD), yıldız (K), kıble (G).', 'Lodos = güneybatı'),
  _k('kcog-012', 'cografya', 'İklim', 'Nem kavramları', 'Mutlak nem: 1 m³ havadaki su buharı (g)\nMaksimum nem: havanın taşıyabileceği en fazla nem; sıcaklıkla artar\nBağıl nem: mutlak / maksimum · 100. %100 olunca hava doymuştur, yoğuşma başlar.', 'Bağıl nem %'),
  _k('kcog-013', 'cografya', 'İklim', 'Yağış türleri', 'Orografik (yamaç): nemli hava dağ yamacı boyunca yükselir (Doğu Karadeniz)\nKonveksiyonel (yükselim): ısınan hava yükselir (Ekvator, İç Anadolu ilkbahar sağanakları)\nCephesel: sıcak ve soğuk hava kütleleri karşılaşır (Türkiye\'de kış yağışları)', 'Karadeniz = orografik'),
  _k('kcog-014', 'cografya', 'Türkiye İklimi', 'Türkiye\'de yağış dağılımı', 'En çok yağış: Doğu Karadeniz (Rize).\nEn az yağış: Tuz Gölü çevresi (Konya-Aksaray).\nKarasal iklimde en çok yağış ilkbaharda, Akdeniz ikliminde kışın, Karadeniz ikliminde her mevsim (en çok sonbaharda) düşer.', 'Rize en yağışlı'),
  _k('kcog-015', 'cografya', 'Topraklar', 'Toprak türleri', 'Zonal (yerinde oluşan): terra rossa (Akdeniz, kırmızı), çernozyom (kara toprak, bozkır), podzol (Karadeniz, yıkanmış), laterit (Ekvator)\nAzonal (taşınmış): alüvyal (akarsu), kolüvyal (yamaç), moren (buzul), lös (rüzgâr)', 'Terra rossa = Akdeniz'),
  _k('kcog-016', 'cografya', 'Bitki Örtüsü', 'Türkiye\'de bitki örtüsü', 'Akdeniz: maki (yaz kuraklığına dayanıklı), kızılçam\nKaradeniz: gür orman (yayvan yapraklı ve iğne yapraklı karışık)\nİç Anadolu: bozkır (step), ilkbahar yağışlarıyla yeşerir, yazın kurur\nDoğu Anadolu: yüksek yerlerde alpin çayırlar', 'Maki = Akdeniz'),
  _k('kcog-017', 'cografya', 'Nüfus', 'Türkiye\'de nüfus', 'Nüfus sayımları 1927\'de başladı; 2007\'den beri Adrese Dayalı Nüfus Kayıt Sistemi (ADNKS) kullanılır.\nNüfusun en yoğun olduğu bölge Marmara, en seyrek Doğu Anadolu. Nüfus artış hızı ve doğurganlık azalmaktadır.', 'ADNKS 2007'),
  _k('kcog-018', 'cografya', 'Yerleşme', 'Kır yerleşme tipleri', 'Mezra: köye bağlı küçük tarım yerleşmesi\nKom: Doğu Anadolu\'da hayvancılık\nYayla: yaz aylarında hayvancılık ya da turizm\nOba: göçebe çadır yerleşmesi\nDam: İç Anadolu\'da tarım\nAğıl: hayvanların barındığı yer', 'Kom = Doğu Anadolu'),
  _k('kcog-019', 'cografya', 'Ekonomik Faaliyetler', 'Türkiye\'de önemli tarım ürünleri', 'Fındık: Karadeniz (Ordu, Giresun)\nÇay: Doğu Karadeniz (Rize)\nPamuk: Güneydoğu (Şanlıurfa/Harran), Çukurova, Ege\nZeytin: Ege ve Güney Marmara\nTurunçgiller: Akdeniz kıyıları\nŞeker pancarı: İç Anadolu (Konya)\nBuğday: İç Anadolu', 'Pamuk = Harran'),
  _k('kcog-020', 'cografya', 'Ekonomik Faaliyetler', 'Türkiye\'de önemli madenler', 'Bor: Eskişehir, Kütahya, Balıkesir (dünya rezervinin büyük kısmı Türkiye\'de)\nKrom: Elazığ (Guleman), Muğla\nDemir: Sivas (Divriği), Malatya (Hekimhan)\nBakır: Artvin (Murgul), Kastamonu (Küre), Elazığ (Maden)\nTaş kömürü: Zonguldak', 'Bor = dünya lideri'),
  _k('kcog-021', 'cografya', 'Enerji', 'Türkiye\'de enerji kaynakları', 'Hidroelektrik: en büyük santral Atatürk Barajı (Fırat)\nJeotermal: Denizli (Sarayköy), Aydın\nRüzgâr: Ege ve Marmara kıyıları\nGüneş: güney ve iç kesimler (Karapınar-Konya)\nLinyit: Afşin-Elbistan, Soma', 'Atatürk Barajı'),
  _k('kcog-022', 'cografya', 'Göç', 'Göç türleri', 'İç göç: ülke içinde (kırdan kente)\nDış göç: ülkeler arası (1961 sonrası Almanya\'ya işçi göçü)\nBeyin göçü: nitelikli insan gücünün yurt dışına gitmesi\nMevsimlik göç: tarım işçileri, turizm çalışanları', 'Beyin göçü'),
  _k('kcog-023', 'cografya', 'Doğal Afetler', 'Türkiye\'de doğal afetler', 'Deprem: Kuzey ve Doğu Anadolu fay hatları başta olmak üzere\nHeyelan: en çok Karadeniz (eğim, yağış, kil)\nÇığ: Doğu Anadolu ve Doğu Karadeniz\nSel: yoğun sağanak ve bitki örtüsü tahribi\nErozyon: İç ve Güneydoğu Anadolu', 'Heyelan = Karadeniz'),
  _k('kcog-024', 'cografya', 'Çevre', 'Küresel çevre sorunları', 'Küresel ısınma: sera gazları (CO₂, metan) → buzulların erimesi, deniz seviyesinin yükselmesi\nOzon incelmesi: CFC gazları; Montreal Protokolü (1987)\nKyoto Protokolü ve Paris Anlaşması: sera gazı azaltımı', 'CFC → ozon'),
  _k('kcog-025', 'cografya', 'Türkiye\'nin Yer Şekilleri', 'Türkiye\'nin önemli akarsuları', 'Kızılırmak: Türkiye\'nin en uzun akarsuyu, Karadeniz\'e dökülür\nFırat ve Dicle: Basra Körfezi\'ne\nSakarya, Yeşilırmak: Karadeniz\'e\nMenderes, Gediz: Ege\'ye\nSeyhan, Ceyhan: Akdeniz\'e\nAras ve Kura: Hazar Denizi\'ne', 'En uzun Kızılırmak'),
  _k('kcog-026', 'cografya', 'Türkiye\'nin Yer Şekilleri', 'Türkiye\'nin gölleri', 'Tektonik: Hazar (Elazığ), Eğirdir, Beyşehir\nVolkanik set: Van Gölü (en büyük göl, sodalı)\nKarstik: Avlan, Suğla\nHeyelan set: Tortum, Sera\nTuz Gölü: tektonik, çok tuzlu, sığ', 'Van Gölü = volkanik set'),
  _k('kcog-027', 'cografya', 'Bölgeler', 'Türkiye\'nin coğrafi bölgeleri', 'Yedi bölge (1941 Birinci Coğrafya Kongresi): Marmara, Ege, Akdeniz, Karadeniz, İç Anadolu, Doğu Anadolu, Güneydoğu Anadolu.\nEn büyük bölge Doğu Anadolu, en küçük Güneydoğu Anadolu.', '1941 Coğrafya Kongresi'),
  _k('kcog-028', 'cografya', 'Ekonomik Faaliyetler', 'GAP (Güneydoğu Anadolu Projesi)', 'Fırat ve Dicle üzerindeki barajlar ve sulama kanalları ile tarım, enerji ve sanayi gelişimini hedefleyen bölgesel kalkınma projesi. Harran Ovası\'nda pamuk üretimi arttı.', 'Harran sulaması'),
  _k('kcog-029', 'cografya', 'Nüfus', 'Demografik dönüşüm', '1. aşama: yüksek doğum-yüksek ölüm\n2. aşama: ölümler azalır, nüfus hızla artar\n3. aşama: doğumlar azalır\n4. aşama: düşük doğum-düşük ölüm, yaşlanan nüfus (gelişmiş ülkeler)', '4 aşama'),
  _k('kcog-030', 'cografya', 'Türkiye\'nin Konumu', 'Türkiye\'nin özel konumu', 'Asya ile Avrupa arasında köprü; üç tarafı denizlerle çevrili; Boğazlar (İstanbul ve Çanakkale) Karadeniz\'i Akdeniz\'e bağlar; enerji koridoru ve jeopolitik öneme sahiptir; ortalama yükseltisi fazladır (≈1132 m).', 'Köprü konumu'),

  // ─── FELSEFE ───────────────────────────────────────────
  _k('kfel-001', 'felsefe', 'Felsefeye Giriş', 'Felsefe nedir?', 'Yunanca “philosophia”: bilgelik sevgisi. Varlık, bilgi ve değerler üzerine akla dayalı, eleştirel, sistemli düşünme etkinliğidir. Soruları cevaplardan daha önemlidir.', 'Bilgelik sevgisi'),
  _k('kfel-002', 'felsefe', 'Felsefeye Giriş', 'Felsefenin alanları', 'Bilgi felsefesi (epistemoloji), varlık felsefesi (ontoloji), ahlak felsefesi (etik), sanat felsefesi (estetik), siyaset felsefesi, bilim felsefesi, din felsefesi, mantık.', 'Epistemoloji = bilgi'),
  _k('kfel-003', 'felsefe', 'İlk Çağ Felsefesi', 'Sokrates', 'Yazılı eser bırakmadı; öğrencisi Platon aracılığıyla bilinir. Doğurtma (maieutik) ve ironi yöntemi. “Kendini bil.” Erdem bilgidir; kimse bilerek kötülük yapmaz.', 'Maieutik yöntem'),
  _k('kfel-004', 'felsefe', 'İlk Çağ Felsefesi', 'Platon', 'İdealar kuramı: gerçek varlık değişmeyen idealar dünyasıdır; duyular dünyası onun gölgesidir (Mağara alegorisi). “Devlet” eserinde yönetimi filozof-krallara bırakır.', 'Mağara alegorisi'),
  _k('kfel-005', 'felsefe', 'İlk Çağ Felsefesi', 'Aristoteles', 'Mantığın kurucusu (Organon). Varlığı madde ve form ile açıklar. Ahlakta “altın orta”: erdem iki aşırılığın ortasıdır (cesaret: korkaklık ile atılganlık arası).', 'Altın orta'),
  _k('kfel-006', 'felsefe', 'Mantık', 'Aristoteles\'in düşünce ilkeleri', 'Özdeşlik: A, A\'dır.\nÇelişmezlik: A hem A hem A değil olamaz.\nÜçüncü hâlin olanaksızlığı: A ya B\'dir ya B değildir.\nYeter-sebep ilkesi (Leibniz): her şeyin bir nedeni vardır.', 'A = A'),
  _k('kfel-007', 'felsefe', 'İslam Felsefesi', 'Farabi ve İbn Sina', 'Farabi: “İkinci öğretmen” (Aristoteles\'ten sonra); El-Medinetü\'l-Fazıla (Erdemli Şehir).\nİbn Sina: Kitabü\'ş-Şifa (felsefe), El-Kanun fi\'t-Tıb (tıp); varlığı zorunlu ve mümkün olarak ayırdı.', 'İkinci öğretmen'),
  _k('kfel-008', 'felsefe', 'Yeni Çağ Felsefesi', 'Descartes', 'Rasyonalist. Yöntemsel şüphe ile her şeyden şüphe edip şüphe edilemeyen “Düşünüyorum, öyleyse varım.” (cogito) sonucuna ulaştı. Doğuştan fikirleri kabul eder.', 'Cogito'),
  _k('kfel-009', 'felsefe', 'Yeni Çağ Felsefesi', 'Locke ve Hume', 'Locke: zihin doğuşta boş levhadır (tabula rasa), bilgi deneyimle gelir.\nHume: bilgilerimiz izlenimlerden gelir; nedensellik yalnızca alışkanlıktır, zorunlu değildir.', 'Tabula rasa'),
  _k('kfel-010', 'felsefe', 'Yeni Çağ Felsefesi', 'Kant', 'Kritisizm (eleştirel felsefe): bilgi, deneyimden gelen malzeme ile aklın kategorilerinin birleşmesidir. Ahlakta ödev ve koşulsuz buyruk: “Öyle davran ki eyleminin ilkesi evrensel bir yasa olabilsin.”', 'Ödev ahlakı'),
  _k('kfel-011', 'felsefe', '19. Yüzyıl', 'Hegel ve Marx', 'Hegel: diyalektik (tez-antitez-sentez); tarih, mutlak tinin kendini gerçekleştirmesidir.\nMarx: diyalektik materyalizm; toplumun temelini ekonomik ilişkiler (alt yapı) belirler.', 'Tez-antitez-sentez'),
  _k('kfel-012', 'felsefe', '19. Yüzyıl', 'Comte ve pozitivizm', 'Yalnızca gözlem ve deneyle doğrulanabilen bilgi geçerlidir. İnsanlık düşüncesi üç hâlden geçer: teolojik, metafizik, pozitif. Sosyolojinin kurucusu sayılır.', 'Üç hâl yasası'),
  _k('kfel-013', 'felsefe', '20. Yüzyıl', 'Pragmatizm ve sezgicilik', 'Pragmatizm (William James, Dewey): işe yarayan, fayda sağlayan bilgi doğrudur.\nEntüisyonizm (Bergson): gerçek bilgiye akılla değil sezgiyle ulaşılır.', 'Fayda / sezgi'),
  _k('kfel-014', 'felsefe', '20. Yüzyıl', 'Varoluşçuluk', 'Sartre: “Varoluş özden önce gelir.” İnsan önce var olur, sonra seçimleriyle kendini tanımlar; özgürdür ve seçimlerinden sorumludur. Kierkegaard ve Heidegger de önemli temsilcilerdir.', 'Varoluş özden önce'),
  _k('kfel-015', 'felsefe', '20. Yüzyıl', 'Nietzsche', 'Değerlerin yeniden değerlendirilmesini savundu; “üstinsan” kavramı ve “güç istenci”. Sürü ahlakını eleştirdi.', 'Üstinsan'),
  _k('kfel-016', 'felsefe', 'Bilgi Felsefesi', 'Bilginin kaynağı tartışması', 'Rasyonalizm: akıl (Descartes)\nEmpirizm: deney (Locke, Hume)\nKritisizm: akıl + deney (Kant)\nEntüisyonizm: sezgi (Bergson)\nPozitivizm: bilimsel olgular (Comte)', 'Akıl mı deney mi?'),
  _k('kfel-017', 'felsefe', 'Varlık Felsefesi', 'Varlık sorusuna cevaplar', 'Materyalizm: varlık maddedir (Demokritos: atom)\nİdealizm: varlık düşünce/idedir (Platon, Hegel)\nDüalizm: madde ve ruh (Descartes)\nOluş: her şey değişir (Herakleitos)', 'Madde mi fikir mi?'),
  _k('kfel-018', 'felsefe', 'Ahlak Felsefesi', 'Ahlak görüşleri', 'Hedonizm: haz (Epikuros)\nUtilitarizm (faydacılık): en çok kişiye en çok mutluluk (Bentham, Mill)\nÖdev ahlakı: Kant\nErdem etiği: Aristoteles\nNihilizm: evrensel ahlak yasası yoktur', 'En çok kişiye en çok fayda'),
  _k('kfel-019', 'felsefe', 'Siyaset Felsefesi', 'Toplum sözleşmesi kuramları', 'Hobbes: doğal durum savaş hâlidir, mutlak egemen gerekir.\nLocke: doğal haklar (yaşam, özgürlük, mülkiyet); sınırlı devlet.\nRousseau: “genel irade”, halk egemenliği.\nMontesquieu: kuvvetler ayrılığı (Kanunların Ruhu).', 'Kuvvetler ayrılığı = Montesquieu'),
  _k('kfel-020', 'felsefe', 'Bilim Felsefesi', 'Popper ve Kuhn', 'Popper: bilimsel teori yanlışlanabilir olmalıdır; bilim deneme-yanılmayla ilerler.\nKuhn: bilim, paradigma değişimleriyle (bilimsel devrimlerle) ilerler.', 'Yanlışlanabilirlik / paradigma'),
  _k('kfel-021', 'felsefe', 'Sanat Felsefesi', 'Sanat görüşleri', 'Taklit (Platon, Aristoteles), yaratma (Kant: dehanın ürünü), sezgi (Croce), duygu aktarımı (Tolstoy), oyun (Schiller), tinin dışavurumu (Hegel).', 'Croce = sezgi'),
  _k('kfel-022', 'felsefe', 'Mantık', 'Tümevarım, tümdengelim, analoji', 'Tümdengelim: genelden özele, zorunlu sonuç (kıyas)\nTümevarım: özelden genele, olası sonuç (deneysel bilimler)\nAnaloji: benzerlikten hareketle sonuç çıkarma', 'Genelden özele = tümdengelim'),
  _k('kfel-023', 'felsefe', 'Mantık', 'Kavram, önerme, çıkarım', 'Kavram: nesnenin zihindeki tasarımı (terim ile dile gelir)\nÖnerme: doğru ya da yanlış olabilen yargı\nÇıkarım: öncüllerden sonuca varma\nTanım türleri: gerçek, sözcük, işaret tanımı', 'Önerme = yargı'),
  _k('kfel-024', 'felsefe', 'Din Felsefesi', 'Tanrı\'nın varlığına ilişkin görüşler', 'Teizm: Tanrı var ve evrene müdahale eder\nDeizm: Tanrı evreni yarattı ama müdahale etmez\nPanteizm: Tanrı ve evren birdir (Spinoza)\nAgnostisizm: bilinemez\nAteizm: Tanrı yoktur', 'Deizm = müdahale etmez'),
  _k('kfel-025', 'felsefe', 'Felsefenin Doğuşu', 'İlk filozoflar (Doğa filozofları)', 'Arkhe (ana madde) arayışı: Thales su, Anaksimenes hava, Herakleitos ateş, Empedokles dört öğe (su, hava, toprak, ateş), Demokritos atom, Pythagoras sayı.', 'Thales = su'),

  // ─── DİN KÜLTÜRÜ ───────────────────────────────────────
  _k('kdin-001', 'din', 'İnanç', 'İmanın esasları', 'Allah\'a, meleklere, kitaplara, peygamberlere, ahiret gününe, kader ve kazaya iman.\nÂmentü duasında sayılır.', '6 esas'),
  _k('kdin-002', 'din', 'İbadet', 'İslam\'ın şartları', 'Kelime-i şehadet getirmek, namaz kılmak, oruç tutmak, zekât vermek, gücü yetenin hacca gitmesi.', '5 şart'),
  _k('kdin-003', 'din', 'İbadet', 'Zekât', 'Nisap miktarı mala sahip olan Müslümanın, üzerinden bir yıl geçen malının genellikle 1/40\'ını (%2,5) belirli kişilere vermesidir. Mali bir ibadettir.', '1/40'),
  _k('kdin-004', 'din', 'İbadet', 'Haccın farzları', 'İhrama girmek (şart), Arafat\'ta vakfe yapmak ve Kâbe\'yi ziyaret tavafı (rükün).\nHac, ömürde bir kez ve gücü yetene farzdır.', 'İhram, Arafat, tavaf'),
  _k('kdin-005', 'din', 'Kur\'an', 'Kur\'an-ı Kerim hakkında temel bilgiler', '114 sure, yaklaşık 6236 ayet. 23 yılda indirildi. İlk inen ayetler Alak suresinin ilk beş ayeti; mushafta ilk sure Fatiha, son sure Nas. Hz. Ebubekir döneminde kitap hâlinde toplandı, Hz. Osman döneminde çoğaltıldı.', '114 sure'),
  _k('kdin-006', 'din', 'Hz. Muhammed', 'Hz. Muhammed\'in hayatından önemli olaylar', 'Hicret (622), Bedir Savaşı (624), Uhud (625), Hendek (627), Hudeybiye Antlaşması (628), Mekke\'nin fethi (630), Veda Haccı ve Veda Hutbesi (632).', 'Hicret 622'),
  _k('kdin-007', 'din', 'İslam Tarihi', 'Dört halife dönemi', 'Hz. Ebubekir, Hz. Ömer, Hz. Osman, Hz. Ali (632-661).\nHz. Ebubekir: Kur\'an\'ın kitap hâline getirilmesi\nHz. Ömer: hicri takvim, fetihler\nHz. Osman: Kur\'an\'ın çoğaltılması', 'Ebubekir-Ömer-Osman-Ali'),
  _k('kdin-008', 'din', 'İslam Düşüncesi', 'İtikadi ve fıkhi mezhepler', 'İtikadi (inanç): Maturidilik, Eşarilik\nFıkhi (amel): Hanefilik, Şafiilik, Malikilik, Hanbelilik\nTürkiye\'de çoğunluk itikatta Maturidi, amelde Hanefidir.', 'Maturidi-Hanefi'),
  _k('kdin-009', 'din', 'İslam Düşüncesi', 'Tasavvufi yorumlar', 'Yesevilik (Hoca Ahmet Yesevi), Mevlevilik (Mevlana), Kadirilik, Nakşibendilik, Bektaşilik (Hacı Bektaş-ı Veli), Bayramilik.\nAlevilik-Bektaşilikte cem, semah ve musahiplik önemlidir.', 'Cem ve semah'),
  _k('kdin-010', 'din', 'İbadet', 'Farz, vacip, sünnet', 'Farz: yapılması kesin emredilen (namaz)\nVacip: kuvvetli delille emredilen (vitir namazı, kurban — Hanefiye göre)\nSünnet: Hz. Peygamber\'in yaptığı\nMübah: yapılması serbest\nMekruh: yapılmaması daha iyi olan', 'Farz > vacip > sünnet'),
  _k('kdin-011', 'din', 'Dinler Tarihi', 'Yahudilik', 'Tek tanrılı; kutsal kitap Tevrat (Tanah); peygamberi Hz. Musa. Mabet: sinagog; kutsal gün Cumartesi (Şabat).', 'Sinagog, Şabat'),
  _k('kdin-012', 'din', 'Dinler Tarihi', 'Hristiyanlık', 'Kutsal kitap İncil (Kitab-ı Mukaddes\'in Yeni Ahit bölümü). Temel inanç teslis (üçleme). Mezhepler: Katoliklik, Ortodoksluk, Protestanlık. Mabet: kilise; kutsal gün Pazar.', 'Teslis'),
  _k('kdin-013', 'din', 'Dinler Tarihi', 'Hinduizm ve Budizm', 'Hinduizm: kutsal metinler Vedalar; kast sistemi, reenkarnasyon (samsara) ve karma inancı.\nBudizm: kurucusu Buda (Siddhartha Gautama); dört yüce gerçek, sekiz dilimli yol, nirvana; kutsal metin Tripitaka.', 'Nirvana = Budizm'),
  _k('kdin-014', 'din', 'Ahlak', 'Temel ahlaki kavramlar', 'Tevbe: günahtan pişmanlık duyup Allah\'a yönelmek\nİhlas: ibadeti yalnız Allah rızası için yapmak\nTevekkül: çalıştıktan sonra sonucu Allah\'a bırakmak\nSabır, adalet, emanet, doğruluk', 'Tevekkül = önce çalış'),
  _k('kdin-015', 'din', 'İnanç', 'Kaza ve kader', 'Kader: Allah\'ın olacak her şeyi ezelde bilip belirlemesi\nKaza: bu belirlenenlerin zamanı gelince gerçekleşmesi\nİnsan iradesiyle seçimlerinden sorumludur (cüz\'i irade).', 'Cüz\'i irade'),
  _k('kdin-016', 'din', 'Kur\'an', 'Kur\'an\'ın ana konuları', 'İnanç (tevhid, nübüvvet, ahiret), ibadet, ahlak ve kıssalar (geçmiş peygamber ve toplumların öyküleri). Kıssaların amacı ibret ve öğüt vermektir.', 'Tevhid-nübüvvet-ahiret'),
  _k('kdin-017', 'din', 'Türk-İslam Kültürü', 'Ahilik', 'Ahi Evran tarafından 13. yüzyılda Anadolu\'da kurulan esnaf ve sanatkâr teşkilatı. Dürüst ticaret, mesleki eğitim, yardımlaşma ve ahlak ilkelerini esas alır.', 'Esnaf teşkilatı'),
  _k('kdin-018', 'din', 'İbadet', 'Oruç', 'Ramazan ayında imsak vaktinden iftar vaktine kadar yeme, içme ve orucu bozan davranışlardan uzak durmaktır. Hastalar ve yolcular sonra kaza edebilir. Kadir Gecesi Ramazan ayındadır.', 'İmsak-iftar'),
  _k('kdin-019', 'din', 'Peygamberler', 'Peygamberlerin özellikleri', 'Sıdk (doğruluk), emanet (güvenilirlik), ismet (günah işlememe), fetanet (akıllılık), tebliğ (vahyi eksiksiz iletme).', 'Beş sıfat'),
  _k('kdin-020', 'din', 'Kutsal Kitaplar', 'İlahi kitaplar ve peygamberleri', 'Tevrat: Hz. Musa\nZebur: Hz. Davud\nİncil: Hz. İsa\nKur\'an-ı Kerim: Hz. Muhammed\nAyrıca bazı peygamberlere suhuf (sayfalar) verilmiştir.', 'Zebur = Davud'),

  // ─── İNGİLİZCE (YDT kelime ve dil bilgisi) ─────────────
  _k('king-001', 'ingilizce', 'Kelime', 'abandon', 'terk etmek, vazgeçmek\nThey had to abandon the project due to lack of funds.', 'Bırakıp gitmek'),
  _k('king-002', 'ingilizce', 'Kelime', 'acquire', 'edinmek, kazanmak (bilgi, beceri)\nChildren acquire language skills naturally.', 'Edinmek'),
  _k('king-003', 'ingilizce', 'Kelime', 'adequate', 'yeterli, uygun\nThe water supply was not adequate for the whole city.', 'Yeterli'),
  _k('king-004', 'ingilizce', 'Kelime', 'approach', 'yaklaşım; yaklaşmak\nA new approach to learning helped the students.', 'Yaklaşım'),
  _k('king-005', 'ingilizce', 'Kelime', 'assume', 'varsaymak, üstlenmek\nWe cannot assume that the results are accurate.', 'Varsaymak'),
  _k('king-006', 'ingilizce', 'Kelime', 'beneficial', 'faydalı, yararlı\nRegular exercise is beneficial to health.', 'Yararlı'),
  _k('king-007', 'ingilizce', 'Kelime', 'consequence', 'sonuç (genellikle olumsuz)\nClimate change has serious consequences.', 'Sonuç'),
  _k('king-008', 'ingilizce', 'Kelime', 'decline', 'azalmak, düşüş; reddetmek\nThe population of the village declined sharply.', 'Düşüş'),
  _k('king-009', 'ingilizce', 'Kelime', 'determine', 'belirlemek, karar vermek\nGenes partly determine our height.', 'Belirlemek'),
  _k('king-010', 'ingilizce', 'Kelime', 'emerge', 'ortaya çıkmak\nNew problems emerged during the research.', 'Ortaya çıkmak'),
  _k('king-011', 'ingilizce', 'Kelime', 'enhance', 'geliştirmek, artırmak\nMusic can enhance concentration.', 'İyileştirmek'),
  _k('king-012', 'ingilizce', 'Kelime', 'evidence', 'kanıt\nThere is no evidence to support this claim.', 'Kanıt'),
  _k('king-013', 'ingilizce', 'Kelime', 'feasible', 'uygulanabilir, yapılabilir\nThe plan is technically feasible.', 'Yapılabilir'),
  _k('king-014', 'ingilizce', 'Kelime', 'reveal', 'ortaya çıkarmak, açığa vurmak\nThe study revealed a link between sleep and memory.', 'Açığa çıkarmak'),
  _k('king-015', 'ingilizce', 'Kelime', 'sustain', 'sürdürmek, devam ettirmek\nIt is hard to sustain motivation for a long time.', 'Sürdürmek'),
  _k('king-016', 'ingilizce', 'Kelime', 'significant', 'önemli, kayda değer\nThere was a significant increase in sales.', 'Kayda değer'),
  _k('king-017', 'ingilizce', 'Kelime', 'vulnerable', 'savunmasız, korunmasız\nOld people are more vulnerable to the disease.', 'Savunmasız'),
